import os
abs_path = os.path.abspath(dirpath)
if not os.path.isdir(abs_path):
    result = {'error': f'目录不存在: {dirpath}'}
else:
    entries = []
    for e in sorted(os.scandir(abs_path), key=lambda x: x.name):
        entries.append({'name': e.name, 'is_dir': e.is_dir(), 'size': e.stat().st_size if e.is_file() else 0})
    result = {'dirpath': abs_path, 'count': len(entries), 'entries': entries[:100]}
